css:
/* ==========================================================================
   Single blog post, Sun State layout: dark masthead with breadcrumb and meta chips,
   "On this page" sidebar, article column, "More from the blog" band, call-to-action band.
   Loaded on this post only. The masthead (date + h1) is built by the platform, so it is
   restyled here rather than authored as blocks. Buttons are styled globally.
   ========================================================================== */
:root{
  --accent:#ff6b3d; --accent-dark:#e0522a;
  --ink:#151515; --muted:#6b6a66; --line:#d8d8d4; --card:#ffffff; --paper:#e6e6e4; --night:#2b2a27;
  --container:1266px;
}
body{background:#fff;color:var(--ink);-webkit-font-smoothing:antialiased}
article{position:relative}
.bz-block h1,.bz-block h2,.bz-block h3{text-transform:uppercase;letter-spacing:0;font-weight:700}
/* ---- Masthead ---------------------------------------------------------------- */
article>.bz-block:first-child{position:relative;isolation:isolate;padding:0;color:#fff;background:#151515 url(/images/hero-truck.jpg) center/cover no-repeat}
article>.bz-block:first-child::before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(8,10,14,.78) 0%,rgba(8,10,14,.6) 55%,rgba(8,10,14,.8) 100%)}
article>.bz-block:first-child>.bz-container{max-width:var(--container);padding:176px 30px 64px;display:flex;flex-direction:column}
article>.bz-block:first-child h1{order:1;color:#fff;max-width:17em;margin:0 0 var(--space-4);font-size:clamp(1.75rem,3.6vw,2.875rem);line-height:1.08;letter-spacing:.02em}
article>.bz-block:first-child .bz-eyebrow{order:2;margin:0;display:flex;flex-wrap:wrap;align-items:center;gap:8px 10px;font:700 .6875rem/1.4 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.88)}
article>.bz-block:first-child .bz-eyebrow::before{content:"International Trucks Model Features";padding:5px 10px;background:var(--accent);color:#fff;letter-spacing:.2em}
article>.bz-block:first-child .bz-eyebrow::after{content:"\00b7\00a0\00a0Rechtien International Trucks";white-space:pre}
/* The cover is the card image on the blog page; the masthead already has its own photo. */
article>.bz-block:first-child>.bz-container+.bz-container{display:none}
/* ---- Breadcrumb: sits over the masthead ---------------------------------------- */
[data-bz-node="p-crumbs"]{position:absolute;top:122px;left:0;right:0;z-index:2;padding:0}
[data-bz-node="p-crumbs"] .bz-container{max-width:var(--container);padding-inline:30px}
[data-bz-node="p-crumbs"] p{margin:0;font:700 .6875rem/1.4 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:#fff}
[data-bz-node="p-crumbs"] a{color:#fff;border-bottom:1px solid transparent;transition:border-color .18s ease}
[data-bz-node="p-crumbs"] a:hover{border-bottom-color:currentColor}
/* ---- Article layout ---------------------------------------------------------------- */
.bz-section[data-bz-node="p-main"]{padding-block:clamp(40px,5vw,72px)}
[data-bz-node="p-main"]>.bz-container{max-width:1120px}
[data-bz-node="p-row"]{align-items:flex-start}
[data-bz-node="p-side"]{position:sticky;top:24px;align-self:flex-start}
[data-bz-node="p-content"]{max-width:760px}
main .bz-block{padding-block:0}
/* Sidebar: table of contents */
[data-bz-node="p-toc-h"] h3{font:700 .625rem/1.4 var(--font-body);letter-spacing:.22em;color:var(--muted);margin:0 0 var(--space-3)}
[data-bz-node="p-toc"] .bz-text{max-width:none}
[data-bz-node="p-toc"] p{margin:0;font-size:.8125rem;line-height:1.4;border-top:1px solid var(--line)}
[data-bz-node="p-toc"] p:last-child{border-bottom:1px solid var(--line)}
[data-bz-node="p-toc"] a{display:block;padding:11px 0;font-weight:600;color:var(--ink);transition:color .18s ease,padding-left .18s ease}
[data-bz-node="p-toc"] a:hover{color:var(--accent-dark);padding-left:4px}
/* Sidebar: card */
[data-bz-node="p-aside"]{margin-top:var(--space-6);padding:22px 22px 18px;background:var(--card);border:1px solid var(--line);border-radius:4px}
[data-bz-node="p-aside-h"] h3{margin:0 0 var(--space-2);font-size:1.0625rem;line-height:1.15}
[data-bz-node="p-aside-t"]{margin-bottom:var(--space-3)}
[data-bz-node="p-aside-t"] p{margin:0;font-size:.8125rem;line-height:1.65;color:#3d3c39}
[data-bz-node="p-aside"] .bz-btns{margin:0}
/* Article body */
[data-bz-node="p-content"] .bz-text p{margin:0 0 var(--space-4);font-size:.9375rem;line-height:1.8;color:#2f2e2b}
[data-bz-node="p-content"] .bz-text a{color:var(--accent-dark);text-decoration:underline;text-underline-offset:3px}
[data-bz-node="p-content"] .bz-text a:hover{color:var(--ink)}
[data-bz-node="p-content"] .bz-block--heading{padding-top:var(--space-6);scroll-margin-top:24px}
[data-bz-node="p-content"] h2{margin:0 0 var(--space-4);font-size:clamp(1.375rem,2.2vw,1.875rem);line-height:1.1;scroll-margin-top:96px}
[data-bz-node="p-intro-cta"] .bz-btns{display:flex;flex-wrap:wrap;gap:12px;margin:var(--space-2) 0 var(--space-4)}
[data-bz-node$="-lead"] p{margin-bottom:var(--space-3)!important;color:var(--ink)!important}
/* Lists inside the article: a single column of rows */
[data-bz-node="p-content"] .bz-block--list .bz-container{padding:0;max-width:none}
[data-bz-node="p-content"] .bz-grid{display:block;margin:0 0 var(--space-5);padding:0;list-style:none}
[data-bz-node="p-content"] .bz-feature{margin:0;padding:12px 0 12px 34px;position:relative;border-top:1px solid var(--line)}
[data-bz-node="p-content"] .bz-feature:last-child{border-bottom:1px solid var(--line)}
[data-bz-node="p-content"] .bz-feature__t{margin:0;font:700 .9375rem/1.5 var(--font-body);text-transform:none;letter-spacing:0;color:var(--ink)}
[data-bz-node="p-content"] .bz-feature__d{margin:2px 0 0;font-size:.9375rem;line-height:1.7;color:#2f2e2b}
/* numbered steps */
[data-bz-node="p-steps"] .bz-grid{counter-reset:step}
[data-bz-node="p-steps"] .bz-feature{counter-increment:step}
[data-bz-node="p-steps"] .bz-feature::before{content:counter(step);position:absolute;left:0;top:13px;width:22px;height:22px;border-radius:50%;background:var(--ink);color:#fff;font:700 .75rem/22px var(--font-body);text-align:center}
/* bullets */
[data-bz-node^="p-bul"] .bz-feature::before{content:"";position:absolute;left:8px;top:21px;width:7px;height:7px;border-radius:50%;background:var(--accent)}
/* comparison table: the first row is the header */
[data-bz-node="p-adv"] .bz-feature{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:4px 24px;padding:14px 16px}
[data-bz-node="p-adv"] .bz-feature__d{margin:0}
[data-bz-node="p-adv"] .bz-feature:first-child{background:var(--ink)}
[data-bz-node="p-adv"] .bz-feature:first-child .bz-feature__t,[data-bz-node="p-adv"] .bz-feature:first-child .bz-feature__d{color:#fff;font:700 .6875rem/1.4 var(--font-body);letter-spacing:.16em;text-transform:uppercase}
/* Disclaimer */
[data-bz-node="p-legal-h"] p{margin:var(--space-5) 0 var(--space-2)!important;font-size:.8125rem!important}
[data-bz-node="p-legal"] p{font-size:.75rem!important;line-height:1.7!important;color:var(--muted)!important}
/* ---- More from the blog ------------------------------------------------------------ */
.bz-section[data-bz-node="p-more"]{padding-block:clamp(48px,5vw,80px)}
[data-bz-node="p-more"] h2{font-size:clamp(1.375rem,2.2vw,1.875rem);line-height:1.1;margin:0}
[data-bz-node="p-more"] .bz-sechead{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:12px 24px;margin-bottom:var(--space-5)}
[data-bz-node="p-more"] .bz-card{background:var(--card);border:1px solid var(--line);border-radius:0}
[data-bz-node="p-more"] .bz-card__t{font:700 1rem/1.25 var(--font-heading);text-transform:uppercase}
[data-bz-node="p-more"] .bz-card__m{font:700 .625rem/1.4 var(--font-body);letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}
[data-bz-node="p-more"] .bz-post__d{font-size:.8125rem;line-height:1.65;color:#3d3c39}
[data-bz-node="p-more"] .bz-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
[data-bz-node="p-more"] .bz-photo{aspect-ratio:16/9;height:auto;min-height:0}
[data-bz-node="p-more"] .bz-photo img{width:100%;height:100%;object-fit:cover}
/* A post should not recommend itself: the "more" list skips this page. */
[data-bz-node="p-more"] a[href$="/90-consistency-s13-2027-transition-technicians"]{display:none}
/* ---- Call to action ------------------------------------------------------------- */
.bz-section[data-bz-node="p-cta"]{padding-block:clamp(56px,6vw,96px);text-align:center;background:var(--night)}
[data-bz-node="p-cta"] .bz-eyebrow{color:rgba(255,255,255,.75)}
[data-bz-node="p-cta"] h2{color:#fff;font-size:clamp(1.5rem,3vw,2.375rem);line-height:1.08;margin:0 0 var(--space-3)}
[data-bz-node="p-cta"] .bz-text p{color:rgba(255,255,255,.9);font-size:.9375rem;line-height:1.75;max-width:36rem;margin:0 auto var(--space-4)}
[data-bz-node="p-cta"] .bz-btns{display:flex;flex-wrap:wrap;justify-content:center;gap:12px 14px}
/* ---- Responsive -------------------------------------------------------------------- */
@media (max-width:900px){
  [data-bz-node="p-more"] .bz-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  article>.bz-block:first-child>.bz-container{padding:172px 20px 48px}
  [data-bz-node="p-crumbs"]{top:104px}
  [data-bz-node="p-crumbs"] .bz-container{padding-inline:20px}
  [data-bz-node="p-side"]{position:static}
  [data-bz-node="p-aside"]{display:none}
}
@media (max-width:640px){
  [data-bz-node="p-more"] .bz-grid{grid-template-columns:1fr}
  [data-bz-node="p-adv"] .bz-feature{grid-template-columns:1fr}
}
